SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"019f9e72-b6dc-7545-99f7-60cd11ca51f2","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Factorise completely: 6y^2 - 15y.","model_answer":"3y(2y - 5)","explanation":"Take out the common factor 3y. This gives 6y^2 - 15y = 3y(2y - 5).","difficulty":"Easy","metadata":{"tags":"algebra,factorisation,common-factor","subtopic":"factorisation","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.884Z","updated_at":"2026-07-26T12:42:25.884Z"},{"id":"019f9e72-b6de-78c6-bd8c-d34069e07a12","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Factorise completely: x^2 - 9x + 20.","model_answer":"(x - 4)(x - 5)","explanation":"Find two numbers whose product is 20 and sum is -9. They are -4 and -5, so the expression factorises to (x - 4)(x - 5).","difficulty":"Easy","metadata":{"tags":"algebra,factorisation,quadratics","subtopic":"quadratic factorisation","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.886Z","updated_at":"2026-07-26T12:42:25.886Z"},{"id":"019f9e72-b6e0-7e2c-84ee-9587e00dc897","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"y is directly proportional to the cube root of (x + 1). It is given that x = 7 when y = 1. Find the value of y when x = 124.","model_answer":"2.5","explanation":"Let y = kΓê¢(x + 1). When x = 7, 1 = kΓê¢8 = 2k, so k = 1/2. When x = 124, y = 1/2 ├ù Γê¢125 = 1/2 ├ù 5 = 2.5.","difficulty":"Medium","metadata":{"tags":"ratio,direct-proportion,cube-root","subtopic":"direct proportion","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.888Z","updated_at":"2026-07-26T12:42:25.888Z"},{"id":"019f9e72-b6e3-75ef-8fce-32f0a433dfb3","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"F is inversely proportional to the square of d. Explain what happens to F when d is halved.","model_answer":"F becomes 4 times the original value.","explanation":"Since F is inversely proportional to d^2, halving d makes d^2 become one quarter of the original value. Therefore F becomes 4 times as large.","difficulty":"Easy","metadata":{"tags":"ratio,inverse-proportion,variation","subtopic":"inverse proportion","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.891Z","updated_at":"2026-07-26T12:42:25.891Z"},{"id":"019f9e72-b6ea-7f6c-bea0-df74736325f2","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"In a cake recipe problem, a matrix product AB is used to combine ingredient amounts with the number of cakes baked. Explain what the entries of AB represent.","model_answer":"They represent the total amounts of each ingredient required.","explanation":"When a matrix of ingredient quantities per cake is multiplied by a matrix showing how many cakes are made, each entry in the product gives the total amount of a particular ingredient needed.","difficulty":"Easy","metadata":{"tags":"matrices,application,interpretation","subtopic":"matrix interpretation","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.898Z","updated_at":"2026-07-26T12:42:25.898Z"},{"id":"019f9ebf-c0c8-72d8-b93d-670b5793463d","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"Express 10 000 SGD in USD if the exchange rate is USD 1 = SGD x.","model_answer":"10000/x","explanation":"If 1 USD = x SGD, then the number of USD received for 10 000 SGD is 10 000 divided by x.","difficulty":"Easy","metadata":{"tags":"ratio,exchange-rates,money","subtopic":"exchange rates","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.695Z","updated_at":"2026-07-26T14:06:34.695Z"},{"id":"019f9ebf-c0d2-7459-98ef-aad8dc14a00a","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"Two exchange rates are given: 1 USD = SGD x in 2023, and in 2022 the rate was SGD 0.030 less per USD. The difference in exchanging SGD 10 000 between the two years is USD 166. Write down the equation in x.","model_answer":"10000/x - 10000/(x - 0.030) = 166","explanation":"In 2023, 10 000 SGD gives 10000/x USD. In 2022, 10 000 SGD gives 10000/(x - 0.030) USD. Their difference is 166 USD, so 10000/x - 10000/(x - 0.030) = 166.","difficulty":"Medium","metadata":{"tags":"ratio,exchange-rates,algebra","subtopic":"exchange rates","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.706Z","updated_at":"2026-07-26T14:06:34.706Z"},{"id":"019f9ebf-c0da-7813-b431-055592fa6664","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Show that (7n - 1)^2 - (n - 1)^2 is a multiple of 12 for all integer values of n.","model_answer":"12n(4n - 1)","explanation":"Use the difference of two squares: (7n - 1)^2 - (n - 1)^2 = [(7n - 1) + (n - 1)] [(7n - 1) - (n - 1)] = (8n - 2)(6n). This simplifies to 12n(4n - 1), which is always divisible by 12.","difficulty":"Medium","metadata":{"tags":"numbers,proof,algebra","subtopic":"multiple of 12","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.714Z","updated_at":"2026-07-26T14:06:34.714Z"},{"id":"019f9ebf-c0de-7550-b119-103e3c4ba23a","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Simplify (p - 3n)(4n - 1) / [12n(4n - 1)].","model_answer":"(3n - p)/(12n)","explanation":"Cancel the common factor (4n - 1) from numerator and denominator. Since p - 3n = -(3n - p), the expression becomes (3n - p)/(12n).","difficulty":"Medium","metadata":{"tags":"algebra,fractions,simplification","subtopic":"algebraic fractions","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.718Z","updated_at":"2026-07-26T14:06:34.718Z"},{"id":"019f9ebf-c0e1-7e17-b0f4-c94a7c857d61","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"The green and red lights flash every 6 seconds and 8 seconds respectively. If they start together, how long will it take for them to next flash simultaneously?","model_answer":"24 s","explanation":"Find the least common multiple of 6 and 8. LCM(6, 8) = 24, so they will next flash together after 24 seconds.","difficulty":"Easy","metadata":{"tags":"numbers,lcm,time","subtopic":"lcm","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.721Z","updated_at":"2026-07-26T14:06:34.721Z"},{"id":"019f9ebf-c0e5-7b31-b834-96bab2ec6168","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Express 2250 as a product of its prime factors.","model_answer":"2 ├ù 3^2 ├ù 5^3","explanation":"2250 = 225 ├ù 10 = (3^2 ├ù 5^2) ├ù (2 ├ù 5) = 2 ├ù 3^2 ├ù 5^3.","difficulty":"Easy","metadata":{"tags":"numbers,prime-factorisation","subtopic":"prime factorisation","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.725Z","updated_at":"2026-07-26T14:06:34.725Z"},{"id":"019f9ebf-c0e9-779f-87dc-0cfb78d5ac8a","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"The period P of a pendulum is directly proportional to the square root of its length L. If P increases by 25%, what is the percentage increase in L?","model_answer":"56.25%","explanation":"Since P is proportional to sqrt(L), L is proportional to P^2. If P increases by 25%, then L changes by 1.25^2 = 1.5625. So the increase in L is 56.25%.","difficulty":"Medium","metadata":{"tags":"ratio,proportion,percentage-change","subtopic":"direct proportion","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.729Z","updated_at":"2026-07-26T14:06:34.729Z"},{"id":"019f9ebf-c0ed-76a8-b98d-3f0ba732ac5c","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"The Great Pyramid has surface area 8.30 ├ù 10^4 m^2 and volume 2.45 ├ù 10^4 m^3. A similar replica has volume 9.22 ├ù 10^-6 m^3. Estimate the surface area of the replica.","model_answer":"4.33 ├ù 10^-2 m^2","explanation":"For similar solids, surface area scales with the square of the linear scale and volume scales with the cube. Use the volume ratio to find the linear scale, then square it and apply it to 8.30 ├ù 10^4. This gives approximately 4.33 ├ù 10^-2 m^2.","difficulty":"Hard","metadata":{"tags":"mensuration,similar-shapes,scaling","subtopic":"similar solids","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.733Z","updated_at":"2026-07-26T14:06:34.733Z"},{"id":"019f9ebf-c0f1-7eb2-8663-cafb16ce1472","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"The universal set is the integers from 0 to 10. Set A = {1, 4, 9} and set B = {1, 2, 4, 8}. Describe the elements of set A.","model_answer":"Perfect squares","explanation":"The elements 1, 4 and 9 are the perfect squares in the universal set from 0 to 10.","difficulty":"Easy","metadata":{"tags":"sets,perfect-squares","subtopic":"set description","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.737Z","updated_at":"2026-07-26T14:06:34.737Z"},{"id":"019f9ebf-c0f5-75c8-9b42-505c50871466","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"Find the number of elements in A Γê¬ B, where A = {1, 4, 9} and B = {1, 2, 4, 8}.","model_answer":"5","explanation":"A Γê¬ B = {1, 2, 4, 8, 9}. There are 5 elements in the union.","difficulty":"Easy","metadata":{"tags":"sets,union,number-of-elements","subtopic":"union of sets","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.741Z","updated_at":"2026-07-26T14:06:34.741Z"}]'::json)
